        return [sgn(tgt[0] - src[0]), sgn(tgt[1] - src[1])]

    def step_away(src, tgt):
        return [sgn(src[0] - tgt[0]), sgn(src[1] - tgt[1])]

    def pick_best(moves, score_fn):
        best_move = [0, 0]
        best_score = None
        for m in moves:
